      ],
      "paragraph_starts": [
        {"text": "toujours rien. Il fallut attendre la publication du livre de Farias,", "continues_from_previous": false, "continues_to_next": false},
        {"text": "Heidegger en fut lui-même surpris, mais sut en tirer parti au", "continues_from_previous": false, "continues_to_next": false}
